package com.example.starter.food.domain;

/**
 * 配方生命周期状态：提交 -> 合规审查 -> 批准 -> 量产备案。
 */
public enum RecipeStatus {
    /** 已提交，尚未审查 */
    SUBMITTED,
    /** 合规审查通过（任一违例则整单进入 REJECTED） */
    COMPLIANT,
    /** 合规审查拒绝（整单拒绝，不产生部分记录） */
    REJECTED,
    /** 已批准，版本快照冻结 */
    APPROVED
}

package com.example.starter.food.domain;

/**
 * 量产备案状态。
 */
public enum FilingStatus {
    /** 有效备案，允许量产上报 */
    ACTIVE,
    /** 复审观察：标准更新后旧版本已备案配方须在 90 个自然日内完成复审 */
    REVIEW_PENDING,
    /** 暂停备案：复审不合格、逾期未复审或被新版本替代 */
    SUSPENDED,
    /** 注销终态：注销后量产记录上报一律拒绝 */
    CANCELLED
}

