package com.example.starter.food.domain;

import java.math.BigDecimal;
import java.util.List;

/**
 * 合规评估使用的配方数据（提交数据或批准快照均可还原为该结构复算）。
 */
public record RecipeData(
        String categoryCode,
        List<DirectAdditive> additives,
        List<Ingredient> ingredients) {

    /** 直接加入的添加剂，amount 单位 g/kg（以终产品质量计）。 */
    public record DirectAdditive(String additiveCode, BigDecimal amount) {
    }

    /** 复合配料，proportion 为占终产品质量比例（0~1）。 */
    public record Ingredient(String compoundCode, BigDecimal proportion) {
    }
}

package com.example.starter.food.domain;

import java.math.BigDecimal;

/**
 * 单个添加剂在终产品中的有效用量（直接加入 + 复合配料带入折算）。
 */
public record EffectiveAdditive(
        String additiveCode,
        /** 直接加入量 g/kg */
        BigDecimal directAmount,
        /** 复合配料带入折算量 g/kg */
        BigDecimal carryOverAmount,
        /** 终产品有效含量 g/kg */
        BigDecimal effectiveAmount) {
}

package com.example.starter.food.domain;

import java.math.BigDecimal;

/**
 * 逐项判定明细。itemType=ADDITIVE 为单项限量判定；itemType=FUNCTION_GROUP 为同功能添加剂并用比例判定。
 */
public record ComplianceItem(
        String itemType,
        String additiveCode,
        String additiveName,
        String functionType,
        String source,
        BigDecimal directAmount,
        BigDecimal carryOverAmount,
        BigDecimal effectiveAmount,
        BigDecimal maxAmount,
        BigDecimal ratio,
        boolean pass,
        String message) {
}

package com.example.starter.food.domain;

import java.util.List;

/**
 * 一份配方在指定标准版本下的完整合规报告；任一项违规则 compliant=false，整单拒绝。
 */
public record ComplianceReport(String standardVersion, List<ComplianceItem> items, boolean compliant) {
}

