import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Map;
import java.util.TreeMap;

/**
 * 幂等指纹：对 requestId 与全部业务字段做规范化 JSON 后取 SHA-256。
 * Map 键按字典序排列，列表保持提交顺序，保证同参指纹一致、异参指纹不同。
 */
public final class Fingerprint {

    private Fingerprint() {
    }

    public static String sha256(ObjectMapper mapper, Object... parts) {
        try {
            Object canonical = canonicalize(mapper, parts.length == 1 ? parts[0] : parts);
            byte[] json = mapper.writeValueAsBytes(canonical);
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] digest = md.digest(json);
            StringBuilder sb = new StringBuilder(64);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        } catch (com.fasterxml.jackson.core.JsonProcessingException e) {
            throw new IllegalArgumentException("无法序列化指纹输入", e);
        }
    }

    @SuppressWarnings("unchecked")
    private static Object canonicalize(ObjectMapper mapper, Object value) {
        if (value == null || value instanceof Number || value instanceof Boolean || value instanceof String) {
            return value;
        }
        if (value instanceof Iterable<?> iterable) {
            java.util.List<Object> list = new ArrayList<>();
            for (Object o : iterable) {
                list.add(canonicalize(mapper, o));
            }
            return list;
        }
        if (value.getClass().isArray()) {
            Object[] arr = (Object[]) value;
            java.util.List<Object> list = new ArrayList<>(arr.length);
            for (Object o : arr) {
                list.add(canonicalize(mapper, o));
            }
            return list;
        }
        Map<String, Object> map = mapper.convertValue(value, TreeMap.class);
        TreeMap<String, Object> sorted = new TreeMap<>();
        for (Map.Entry<String, Object> e : map.entrySet()) {
            sorted.put(e.getKey(), canonicalize(mapper, e.getValue()));
        }
        return sorted;
    }

    public static String utf8HexPlaceholder() {
        return new String(StandardCharsets.UTF_8.name().getBytes(StandardCharsets.UTF_8), StandardCharsets.UTF_8);
    }
}

