        if (!stored.fingerprint().equals(fingerprint)) {
            throw new BusinessException(409,
                    "requestId=" + requestId + " 已用于不同的业务参数，拒绝同键异参请求");
        }
        return new Result(true, stored.statusCode(), stored.responseJson());
    }

